import * as ComboboxPrimitive from "@kobalte/core/combobox";
import type { PolymorphicProps } from "@kobalte/core/polymorphic";

import { Button } from "./button.tsx";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "./input-group.tsx";
import { cn } from "~/lib/utils.ts";
import type { Component, ComponentProps, JSX, ValidComponent } from "solid-js";

import { Show, splitProps } from "solid-js";
import IconArrowDown01 from "~icons/hugeicons/arrow-down-01";
import IconCancel01 from "~icons/hugeicons/cancel-01";
import IconTick02 from "~icons/hugeicons/tick-02";

// Kobalte's default triggerMode="input" only opens the popup once the
// user types; upstream's base-ui combobox opens it when the input is
// clicked. triggerMode="focus" is the closest match: clicking the input
// opens the popup (it also opens on keyboard focus, which upstream does
// not do — the smaller mismatch). placement="bottom-start" mirrors
// upstream ComboboxContent's side/align defaults; Kobalte only accepts
// it on the root. Consumers can override both.
const Combobox = <Option, OptGroup = never, T extends ValidComponent = "div">(
  props: PolymorphicProps<
    T,
    ComboboxPrimitive.ComboboxRootProps<Option, OptGroup, T>
  >,
) => (
  <ComboboxPrimitive.Root
    triggerMode="focus"
    placement="bottom-start"
    {...(props as ComboboxPrimitive.ComboboxRootProps<Option, OptGroup>)}
  />
);
const ComboboxItemLabel = ComboboxPrimitive.ItemLabel;
const ComboboxHiddenSelect = ComboboxPrimitive.HiddenSelect;

type ComboboxTriggerProps<T extends ValidComponent = "button"> =
  & ComboboxPrimitive.ComboboxTriggerProps<T>
  & {
    class?: string | undefined;
    children?: JSX.Element;
  };

const ComboboxTrigger = <T extends ValidComponent = "button">(
  props: PolymorphicProps<T, ComboboxTriggerProps<T>>,
) => {
  const [local, others] = splitProps(props as ComboboxTriggerProps, [
    "class",
    "children",
  ]);
  return (
    <ComboboxPrimitive.Trigger
      data-slot="combobox-trigger"
      class={cn("[&_svg:not([class*='size-'])]:size-4", local.class)}
      {...others}
    >
      {local.children}
      <IconArrowDown01
        class="text-muted-foreground size-4 pointer-events-none"
      />
    </ComboboxPrimitive.Trigger>
  );
};

type ComboboxClearProps = ComponentProps<"button">;

const ComboboxClear: Component<ComboboxClearProps> = (props) => {
  const [local, others] = splitProps(props, ["class"]);
  return (
    <InputGroupButton
      data-slot="combobox-clear"
      variant="ghost"
      size="icon-xs"
      aria-label="Clear"
      class={cn(local.class)}
      {...others}
    >
      <IconCancel01
        class="pointer-events-none"
      />
    </InputGroupButton>
  );
};

type ComboboxInputProps<T extends ValidComponent = "input"> =
  & ComboboxPrimitive.ComboboxInputProps<T>
  & {
    class?: string | undefined;
    children?: JSX.Element;
    placeholder?: string;
    "aria-invalid"?: boolean | "true" | "false";
    showTrigger?: boolean;
    showClear?: boolean;
  };

const ComboboxInput = <T extends ValidComponent = "input">(
  props: PolymorphicProps<T, ComboboxInputProps<T>>,
) => {
  const [local, others] = splitProps(props as ComboboxInputProps, [
    "class",
    "children",
    "disabled",
    "showTrigger",
    "showClear",
  ]);
  return (
    <ComboboxPrimitive.Control
      as={InputGroup}
      class={cn("w-auto", local.class)}
    >
      {(state) => (
        <>
          <ComboboxPrimitive.Input
            as={InputGroupInput}
            disabled={local.disabled}
            {...others}
          />
          <InputGroupAddon align="inline-end">
            <Show when={local.showTrigger ?? true}>
              <ComboboxTrigger
                as={InputGroupButton}
                size="icon-xs"
                variant="ghost"
                class="group-has-data-[slot=combobox-clear]/input-group:hidden"
                disabled={local.disabled}
              />
            </Show>
            <Show when={local.showClear && state.selectedOptions().length > 0}>
              <ComboboxClear
                disabled={local.disabled}
                onClick={() => state.clear()}
              />
            </Show>
          </InputGroupAddon>
          {local.children}
        </>
      )}
    </ComboboxPrimitive.Control>
  );
};

type ComboboxChipsProps<Option, T extends ValidComponent = "div"> =
  & ComboboxPrimitive.ComboboxControlProps<Option, T>
  & { class?: string | undefined };

const ComboboxChips = <Option, T extends ValidComponent = "div">(
  props: PolymorphicProps<T, ComboboxChipsProps<Option, T>>,
) => {
  const [local, others] = splitProps(props as ComboboxChipsProps<Option>, [
    "class",
  ]);
  return (
    <ComboboxPrimitive.Control
      data-slot="combobox-chips"
      class={cn("bg-input/50 border-transparent focus-within:border-ring focus-within:ring-ring/30 has-aria-invalid:ring-destructive/20 dark:has-aria-invalid:ring-destructive/40 has-aria-invalid:border-destructive dark:has-aria-invalid:border-destructive/50 flex min-h-9 flex-wrap items-center gap-1.5 rounded-3xl border bg-clip-padding px-3 py-1.5 text-sm transition-[color,box-shadow,background-color] focus-within:ring-3 has-aria-invalid:ring-3 has-data-[slot=combobox-chip]:px-1.5", local.class)}
      {...others}
    />
  );
};

type ComboboxChipProps = ComponentProps<"span"> & {
  showRemove?: boolean;
  onRemove?: () => void;
};

const ComboboxChip: Component<ComboboxChipProps> = (props) => {
  const [local, others] = splitProps(props, [
    "class",
    "children",
    "showRemove",
    "onRemove",
  ]);
  return (
    <span
      data-slot="combobox-chip"
      class={cn(
        "bg-input text-foreground flex h-[calc(--spacing(5.5))] w-fit items-center justify-center gap-1 rounded-3xl px-2 text-xs font-medium whitespace-nowrap has-data-[slot=combobox-chip-remove]:pr-0 dark:bg-input/60 has-disabled:pointer-events-none has-disabled:cursor-not-allowed has-disabled:opacity-50",
        local.class,
      )}
      {...others}
    >
      {local.children}
      <Show when={local.showRemove ?? true}>
        <Button
          data-slot="combobox-chip-remove"
          type="button"
          variant="ghost"
          size="icon-xs"
          class="-ml-1 opacity-50 hover:opacity-100"
          onClick={() => local.onRemove?.()}
        >
          <IconCancel01
            class="pointer-events-none"
          />
        </Button>
      </Show>
    </span>
  );
};

type ComboboxChipsInputProps<T extends ValidComponent = "input"> =
  & ComboboxPrimitive.ComboboxInputProps<T>
  & { class?: string | undefined };

const ComboboxChipsInput = <T extends ValidComponent = "input">(
  props: PolymorphicProps<T, ComboboxChipsInputProps<T>>,
) => {
  const [local, others] = splitProps(props as ComboboxChipsInputProps, [
    "class",
  ]);
  return (
    <ComboboxPrimitive.Input
      data-slot="combobox-chip-input"
      class={cn(
        "min-w-16 flex-1 outline-none",
        local.class,
      )}
      {...others}
    />
  );
};

const ComboboxEmpty: Component<ComponentProps<"div">> = (props) => {
  const [local, others] = splitProps(props, ["class"]);
  return (
    <div
      data-slot="combobox-empty"
      class={cn(
        "text-muted-foreground hidden w-full justify-center py-2 text-center text-sm group-has-[[data-slot=combobox-list]:empty]/combobox-content:flex",
        local.class,
      )}
      {...others}
    />
  );
};

type ComboboxSectionProps<T extends ValidComponent = "li"> =
  & ComboboxPrimitive.ComboboxSectionProps<T>
  & { class?: string | undefined };

const ComboboxSection = <T extends ValidComponent = "li">(
  props: PolymorphicProps<T, ComboboxSectionProps<T>>,
) => {
  const [local, others] = splitProps(props as ComboboxSectionProps, ["class"]);
  return (
    <ComboboxPrimitive.Section
      data-slot="combobox-label"
      class={cn("text-muted-foreground px-3 py-2.5 text-xs", local.class)}
      {...others}
    />
  );
};

// an li, not a div: the listbox is a ul, which may only own list items
const ComboboxSeparator: Component<ComponentProps<"li">> = (props) => {
  const [local, others] = splitProps(props, ["class"]);
  return (
    <li
      data-slot="combobox-separator"
      role="separator"
      aria-orientation="horizontal"
      class={cn("bg-border -mx-1.5 my-1.5 h-px", local.class)}
      {...others}
    />
  );
};

type ComboboxItemProps<T extends ValidComponent = "li"> =
  & ComboboxPrimitive.ComboboxItemProps<T>
  & {
    class?: string | undefined;
    children?: JSX.Element;
  };

const ComboboxItem = <T extends ValidComponent = "li">(
  props: PolymorphicProps<T, ComboboxItemProps<T>>,
) => {
  const [local, others] = splitProps(props as ComboboxItemProps, [
    "class",
    "children",
  ]);
  return (
    <ComboboxPrimitive.Item
      data-slot="combobox-item"
      class={cn(
        "data-highlighted:bg-accent data-highlighted:text-accent-foreground not-data-[variant=destructive]:data-highlighted:**:text-accent-foreground gap-2.5 rounded-2xl py-2 pr-8 pl-3 text-sm font-medium [&_svg:not([class*='size-'])]:size-4 relative flex w-full cursor-default items-center outline-hidden select-none data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0",
        local.class,
      )}
      {...others}
    >
      {local.children}
      <ComboboxPrimitive.ItemIndicator class="pointer-events-none absolute right-2 flex size-4 items-center justify-center">
        <IconTick02
          class="pointer-events-none"
        />
      </ComboboxPrimitive.ItemIndicator>
    </ComboboxPrimitive.Item>
  );
};

type ComboboxContentProps<T extends ValidComponent = "div"> =
  & ComboboxPrimitive.ComboboxContentProps<T>
  & {
    class?: string | undefined;
    children?: JSX.Element;
  };

const ComboboxContent = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, ComboboxContentProps<T>>,
) => {
  const [local, others] = splitProps(props as ComboboxContentProps, ["class"]);
  return (
    <ComboboxPrimitive.Portal>
      <ComboboxPrimitive.Content
        data-slot="combobox-content"
        class={cn(
          // Upstream's min-w-[calc(var(--anchor-width)+--spacing(7))]
          // widens the popup past its anchor (the inner input element) by
          // the 28px trailing chevron addon. Kobalte anchors to the whole
          // control (input + addons), so the +28 is already included:
          // min-w-(--kb-popper-anchor-width) computes the same width, and
          // upstream's data-chips exact-width exception collapses into it.
          "bg-popover text-popover-foreground data-expanded:animate-in data-closed:animate-out data-closed:fade-out-0 data-expanded:fade-in-0 data-closed:zoom-out-95 data-expanded:zoom-in-95 ring-foreground/5 dark:ring-foreground/10 *:data-[slot=input-group]:bg-input/50 *:data-[slot=input-group]:border-input/30 overflow-hidden rounded-3xl shadow-lg ring-1 duration-100 *:data-[slot=input-group]:m-1.5 *:data-[slot=input-group]:mb-0 *:data-[slot=input-group]:h-8 *:data-[slot=input-group]:shadow-none group/combobox-content relative z-50 max-h-(--kb-popper-content-available-height) max-w-(--kb-popper-content-available-width) min-w-(--kb-popper-anchor-width) origin-(--kb-combobox-content-transform-origin)",
          local.class,
        )}
        {...others}
      />
    </ComboboxPrimitive.Portal>
  );
};

type ComboboxListProps<
  Option,
  OptGroup = never,
  T extends ValidComponent = "ul",
> =
  & ComboboxPrimitive.ComboboxListboxProps<Option, OptGroup, T>
  & { class?: string | undefined };

const ComboboxList = <
  Option,
  OptGroup = never,
  T extends ValidComponent = "ul",
>(
  props: PolymorphicProps<T, ComboboxListProps<Option, OptGroup, T>>,
) => {
  const [local, others] = splitProps(
    props as ComboboxListProps<Option, OptGroup>,
    ["class"],
  );
  return (
    <ComboboxPrimitive.Listbox
      data-slot="combobox-list"
      class={cn(
        "no-scrollbar scroll-py-1.5 p-1.5 empty:p-0 max-h-[min(calc(--spacing(72)---spacing(9)),calc(var(--kb-popper-content-available-height)---spacing(9)))] overflow-y-auto overscroll-contain",
        local.class,
      )}
      {...others}
    />
  );
};

export {
  Combobox,
  ComboboxChip,
  ComboboxChips,
  ComboboxChipsInput,
  ComboboxContent,
  ComboboxEmpty,
  ComboboxHiddenSelect,
  ComboboxInput,
  ComboboxItem,
  ComboboxItemLabel,
  ComboboxList,
  ComboboxSection,
  ComboboxSeparator,
  ComboboxTrigger,
};
